 public ShortcutSettingsForm(Keys s,Keys u,Keys v,Keys p){SaveKey=s;UndoKey=u;VerifyKey=v;StopKey=p;Text="Configurar atalhos";ClientSize=new Size(380,245);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(20,21,27);ForeColor=Color.White;Font=new Font("Segoe UI",9);string[] names={"Salvar perfil","Desfazer","Verificar dispositivos","Parar efeito"};ComboBox[] boxes={save=new ComboBox(),undo=new ComboBox(),verify=new ComboBox(),stop=new ComboBox()};Keys[][] values={new[]{Keys.Control|Keys.S,Keys.Control|Keys.Shift|Keys.S},new[]{Keys.Control|Keys.Z,Keys.Control|Keys.Y},new[]{Keys.F5,Keys.F6},new[]{Keys.Escape,Keys.F12}};Keys[] current={s,u,v,p};for(int i=0;i<4;i++){Controls.Add(new Label{Text=names[i],Location=new Point(18,18+i*40),Width=145});boxes[i].DropDownStyle=ComboBoxStyle.DropDownList;boxes[i].SetBounds(175,14+i*40,170,28);foreach(var key in values[i])boxes[i].Items.Add(ThebestRGBKeyName(key));boxes[i].SelectedIndex=Math.Max(0,Array.IndexOf(values[i],current[i]));Controls.Add(boxes[i]);}var ok=ThebestRGB.Button("Salvar",Color.FromArgb(151,119,246));ok.SetBounds(247,190,98,34);Controls.Add(ok);var cancel=ThebestRGB.Button("Cancelar",Color.FromArgb(35,36,45));cancel.SetBounds(135,190,100,34);cancel.DialogResult=DialogResult.Cancel;Controls.Add(cancel);CancelButton=cancel;ok.Click+=delegate{SaveKey=values[0][save.SelectedIndex];UndoKey=values[1][undo.SelectedIndex];VerifyKey=values[2][verify.SelectedIndex];StopKey=values[3][stop.SelectedIndex];DialogResult=DialogResult.OK;Close();};DarkDialogChrome.Attach(this,Text);}
 static string ThebestRGBKeyName(Keys k){return k==Keys.F5?"F5":k==Keys.F6?"F6":k==Keys.Escape?"Esc":k==Keys.F12?"F12":k==(Keys.Control|Keys.Shift|Keys.S)?"Ctrl+Shift+S":k==(Keys.Control|Keys.Y)?"Ctrl+Y":k==(Keys.Control|Keys.Z)?"Ctrl+Z":"Ctrl+S";}
}

